"""Build offline, author-only HTML inspector; contains 48 full private responses.
Never upload this document to a public repository or open reviewer packet.
"""
from pathlib import Path
import json,sys
raw=Path(sys.argv[1])
file=Path(sys.argv[2])
obj=json.loads(raw.read_text(encoding='utf-8'))
assert obj['successful_calls']==48
entries=[]
for e in obj['trajectories']:
    assert len(e['turns'])==2
    entries.append({'moment':e['moment'],'arm':e['arm'],'replicate':e['replicate'],
        'model':e['model'], 'phase1':e['turns'][0]['answer'], 'phase2':e['turns'][1]['answer'],
        'tokens':sum(t['receipt']['input_tokens']+t['receipt']['output_tokens'] for t in e['turns'])})
serialized=json.dumps(entries,ensure_ascii=False).replace('</','<\\/').replace('<!--','<\\!--')
html='''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Shadowseed | Ruwe 48-runverkenner</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#1e2b38;background:#f7f8fa}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1500px;margin:auto;padding:22px}header{background:#152d3c;color:white;padding:24px 0}header h1{font-size:clamp(1.4rem,3vw,2.2rem);margin:0 0 8px}header p{max-width:950px;color:#d5e2e8;line-height:1.6;margin:0}.meta{display:flex;flex-wrap:wrap;gap:16px;margin-top:16px}.metric{background:#21465a;border:1px solid #416479;border-radius:10px;padding:12px 15px;min-width:140px}.metric strong{display:block;font-size:1.4rem}.metric span{font-size:.8rem;color:#c6d6dd}.warning{padding:12px 16px;background:#fff9ee;border-left:4px solid #bf7d1b;margin:19px 0;line-height:1.55}.controls{display:flex;gap:11px;flex-wrap:wrap;margin:14px 0 16px}.controls label{font-size:.85rem;display:grid;gap:5px;font-weight:650}.controls select,.controls input{background:white;border:1px solid #c2ced7;border-radius:7px;padding:10px;font:inherit;min-width:160px}.controls input{width:220px}#count{font-size:.9rem;color:#556a78;margin:6px 0 14px}.item{border:1px solid #d8e0e7;background:white;border-radius:11px;margin-bottom:13px;overflow:hidden;box-shadow:0 2px 3px #22334407}summary{cursor:pointer;padding:15px 17px;display:flex;gap:9px;align-items:center;flex-wrap:wrap;list-style:none}summary::-webkit-details-marker{display:none}summary::before{content:'▸';margin-right:6px;color:#5a768c}details[open] summary::before{content:'▾'}summary b{font-size:1rem}.pill{border:1px solid #cedae3;border-radius:20px;padding:3px 10px;background:#f3f7fa;font-size:.75rem}.tokens{margin-left:auto;color:#526776;font-size:.83rem}.cols{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding:15px;border-top:1px solid #e3e9ef}.response{min-width:0}.response h3{font-size:.95rem;margin:0 0 9px;padding-bottom:9px;border-bottom:1px solid #e3e9ef}.answer{font-family:inherit;white-space:pre-wrap;overflow-wrap:anywhere;font-size:.89rem;line-height:1.62;color:#273846;max-height:650px;overflow:auto;background:#fbfcfd;padding:13px;border:1px solid #ebeff3;border-radius:7px}.hint{font-size:.85rem;color:#677885}.privacy{font-size:.78rem;margin-top:20px;color:#58707f}@media(max-width:720px){.wrap{padding:14px}.cols{grid-template-columns:1fr}.controls{display:grid;grid-template-columns:1fr 1fr}.controls label:last-child{grid-column:1/-1}.controls select{min-width:0}.metric{flex:1;min-width:110px}}
</style></head><body><header><div class="wrap"><h1>Shadow Seed Learning | ruwe vervolgtrajecten</h1><p>Exploratieve proef, 28 oktober 2026. Twee onderzoeksmomenten in één fictieve meetboeicasus, telkens vier armen, drie herhalingen en twee volgbeurten. Gebruik de originele antwoorden, niet voorafgaande interpretaties, om de betekenis van twijfel te onderzoeken.</p><div class="meta"><div class="metric"><strong>48</strong><span>modelantwoorden</span></div><div class="metric"><strong>24</strong><span>vervolgtrajecten</span></div><div class="metric"><strong>187.255</strong><span>gerapporteerde tokens</span></div><div class="metric"><strong>0</strong><span>onafhankelijke menselijke reviews</span></div></div></div></header><main class="wrap"><div class="warning"><b>Alleen voor de onderzoeker.</b> Dit HTML-bestand bevat volledige, niet-geblindeerde modelantwoorden en is niet bedoeld voor publicatie of voor onafhankelijke beoordelaars. De Shadowseed-arm bevat een expliciete, gewichtloze kandidaat als onderzoeksaantekening, geen promotie via de product-Gate. Dit is geen bewijs voor Q1/Q2.</div><div class="controls"><label>Onderzoeksmoment<select id="moment"><option value="all">Alle momenten</option><option value="horizon_after_T2">Horizon, GPT-5, na T2</option><option value="battery_after_T3">Batterij, GPT-6 Luna, na T3</option></select></label><label>Arm<select id="arm"><option value="all">Alle armen</option><option value="ordinary">Gewone generatie</option><option value="deliberate_search">Gericht diep zoeken</option><option value="shadow_candidate">Kandidaat met gewicht nul</option><option value="placebo">Irrelevante kandidaat</option></select></label><label>Herhaling<select id="rep"><option value="all">Alle herhalingen</option><option value="1">Herhaling 1</option><option value="2">Herhaling 2</option><option value="3">Herhaling 3</option></select></label><label>Zoeken in beide antwoorden<input type="search" id="query" placeholder="bijv. klok, horizon, referentie" autocomplete="off"></label></div><div id="count"></div><div id="results"></div><p class="privacy">Bron: oorspronkelijke GitHub Actions-data (observed.json, SHA256 0a5094e38ab2fdcf8c68dc8d6a3c75d29eeffd49e1f6c8e138589ed73ca36bbf) en gecorrigeerde onderzoeksrun #40616375653. De twee momenten zijn niet statistisch onafhankelijk. Iedere kaart toont letterlijke uitvoer, zonder semantische score.</p></main>
<script>const data=DATA_PLACEHOLDER;const names={ordinary:'Gewone generatie',deliberate_search:'Gericht diep zoeken',shadow_candidate:'Gewichtloze kandidaat',placebo:'Irrelevante kandidaat'};
const el=x=>document.getElementById(x);
function render(){const filters={m:el('moment').value,a:el('arm').value,r:el('rep').value,q:el('query').value.toLocaleLowerCase()};
let hits=data.filter(t=>(filters.m==='all'||filters.m===t.moment)&&(filters.a==='all'||filters.a===t.arm)&&(filters.r==='all'||filters.r===String(t.replicate))&&(!filters.q||(t.phase1+' '+t.phase2).toLocaleLowerCase().includes(filters.q)));
hits.sort((a,b)=>a.moment.localeCompare(b.moment)||String(a.arm).localeCompare(String(b.arm))||a.replicate-b.replicate);
el('count').textContent=hits.length+' van de 24 tweebeurttrajecten';const target=el('results');target.replaceChildren();
for(const t of hits){let box=document.createElement('details');box.className='item';let s=document.createElement('summary');let b=document.createElement('b');b.textContent=t.moment==='horizon_after_T2'?'Horizon':'Batterij';s.append(b);let pill=document.createElement('span');pill.className='pill';pill.textContent=names[t.arm];s.append(pill);let rep=document.createElement('span');rep.className='pill';rep.textContent='Herhaling '+t.replicate;s.append(rep);let tk=document.createElement('span');tk.className='tokens';tk.textContent=t.tokens.toLocaleString('nl-NL')+' tokens';s.append(tk);box.append(s);
let cols=document.createElement('div');cols.className='cols';for(const [label,value] of [['Eerste vervolgantwoord',t.phase1],['Tweede vervolgantwoord',t.phase2]]){let c=document.createElement('div');c.className='response';let h=document.createElement('h3');h.textContent=label;let pre=document.createElement('div');pre.className='answer';pre.textContent=value;c.append(h,pre);cols.append(c)}box.append(cols);target.append(box)} }
for(const id of ['moment','arm','rep','query'])el(id).addEventListener(id==='query'?'input':'change',render);render();</script></body></html>'''
file.write_text(html.replace('DATA_PLACEHOLDER',serialized),encoding='utf-8')
print('Offline owner-only explorer:',file, file.stat().st_size,'bytes')
